export function t(key, vars) {
  let s = I18N[key] ? I18N[key][state.currentLang] || I18N[key].en || key : key;
  if (vars) {
    Object.keys(vars).forEach((k) => {
      s = s.split("{" + k + "}").join(vars[k]);
    });
  }
  return s;
}

